import pytest
from app.util import parse_duration


@pytest.mark.parametrize("bad", ["", "5x", "-3m", "m", "1.5h", "90"])
def test_rejects_invalid(bad):
    with pytest.raises(ValueError, match="invalid duration"):
        parse_duration(bad)


@pytest.mark.parametrize("good,seconds", [("90s", 90), ("5m", 300), ("2h", 7200), ("0s", 0)])
def test_keeps_valid(good, seconds):
    assert parse_duration(good) == seconds
